// This tag covers query errors, not only duplicate emails.
yield* db
  .insert(users)
  .values({ name: "Ada again", email: "ada@example.com", credits: 0 })
  .pipe(Effect.catchTag("EffectDrizzleQueryError", (error) => Console.log("Insert failed:", error.cause)));

return yield* db.select()

// An error of your own, with a tag like Drizzle's.
class NotEnoughCredits extends Data.TaggedError("NotEnoughCredits")<{ readonly name: string }> {}

// A program is a plan

// A failed Effect inside the transaction rolls it back.
const spend = (name: string, amount: number) =>
  db.transaction((tx) =>
    Effect.gen(function* () {
      const [user] = yield* tx
        .update(users)
        .set({ credits: sql`${users.credits} - ${amount}` })
        .where(eq(users.name, name))
        .returning();

      if (user === undefined || user.credits < 0) {
        return yield* new NotEnoughCredits({ name });
      }
    }),
  );

yield* spend("Ada", 3);
yield* spend("Grace", 50).pipe(
  Effect.catchTag("NotEnoughCredits", (error) => Console.log(`${error.name} can't spend 50: rolled back`)),
);

return yield* db.select()

